originalCss:
:root {
    --bg: #07111e;
    --panel: #0d1b2e;
    --panel2: #12233b;
    --border: #1f3352;
    --text: #e6edf7;
    --dim: #c7d6ec;
    --faint: #9cb0cf;
    --accent: #7c9eff;
    --side: 300px;
    --warn: #f5b84b;
    --ok: #5fd0a0;
}
* {
    box-sizing: border-box;
}
html,
body {
    margin: 0;
    overflow-x: hidden;
}
body {
    background: var(--bg);
    color: var(--text);
    font-family: 'Noto Sans JP', system-ui, sans-serif;
    font-size: 15.5px;
    line-height: 1.85;
}
.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--side);
    background: var(--panel);
    border-right: 1px solid var(--border);
    overflow-y: auto;
    padding: 20px 14px 40px;
    z-index: 20;
}
.sidebar .brand {
    font-size: 12px;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 700;
    margin: 0 8px 14px;
}
.sidebar ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.sidebar li > ul {
    margin: 2px 0 8px 10px;
    border-left: 1px solid var(--border);
}
.sidebar a {
    display: block;
    color: var(--dim);
    text-decoration: none;
    font-size: 13px;
    line-height: 1.5;
    padding: 6px 10px;
    border-radius: 6px;
}
.sidebar a.sub {
    font-size: 12px;
    color: var(--faint);
    padding: 4px 10px;
}
.sidebar a:hover {
    background: var(--panel2);
    color: #fff;
}
.sidebar a.active {
    background: rgba(124, 158, 255, 0.16);
    color: #fff;
    box-shadow: inset 3px 0 0 var(--accent);
}
.toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 30;
    background: var(--panel2);
    color: var(--text);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 8px 12px;
    font: inherit;
    font-size: 13px;
    cursor: pointer;
}
.main {
    margin-left: var(--side);
    padding: 32px 48px 80px;
}
.hero {
    position: relative;
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 32px 32px 26px;
    margin-bottom: 36px;
    background: var(--panel);
    overflow: hidden;
}
.hero::before {
    content: '';
    position: absolute;
    top: -120px;
    right: -80px;
    width: 420px;
    height: 420px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.22), transparent 65%);
    pointer-events: none;
}
.eyebrow {
    display: inline-block;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.06em;
    color: var(--accent);
    border: 1px solid rgba(124, 158, 255, 0.5);
    background: rgba(124, 158, 255, 0.1);
    border-radius: 999px;
    padding: 3px 14px;
    margin-bottom: 14px;
}
.hero-title {
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.4;
    margin: 0 0 20px;
    position: relative;
}
.meta {
    display: grid;
    grid-template-columns: minmax(0, 1.3fr) minmax(0, 0.7fr) minmax(0, 1.3fr);
    position: relative;
    border-top: 1px solid var(--border);
    padding-top: 16px;
}
.meta-item {
    display: flex;
    flex-direction: column;
    padding: 0 22px;
    border-right: 1px solid var(--border);
    min-width: 0;
}
.meta-item:first-child {
    padding-left: 0;
}
.meta-item:last-child {
    border-right: 0;
}
.meta-label {
    font-size: 11px;
    letter-spacing: 0.08em;
    color: var(--faint);
    text-transform: uppercase;
}
.meta-value {
    font-size: 14.5px;
    color: var(--text);
    line-height: 1.6;
}
h2 {
    font-size: 23px;
    font-weight: 800;
    color: #fff;
    margin: 56px 0 18px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--border);
    scroll-margin-top: 20px;
}
h3 {
    font-size: 18px;
    font-weight: 700;
    color: #dbe6ff;
    margin: 34px 0 12px;
    padding-left: 12px;
    border-left: 3px solid var(--accent);
    scroll-margin-top: 20px;
}
h4 {
    font-size: 16px;
    color: var(--dim);
    margin: 24px 0 8px;
}
p,
li {
    color: var(--text);
}
strong {
    color: #fff;
}
a {
    color: var(--accent);
    word-break: break-all;
}
code:not(pre code) {
    background: var(--panel2);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 1px 6px;
    font-size: 0.9em;
    overflow-wrap: break-word;
}
.table-scroll {
    overflow-x: auto;
    margin: 16px 0 22px;
    border: 1px solid var(--border);
    border-radius: 10px;
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14px;
}
th {
    background: var(--panel2);
    color: #fff;
    text-align: left;
    font-weight: 700;
    white-space: nowrap;
}
th,
td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--border);
    vertical-align: top;
    line-height: 1.65;
}
td {
    color: var(--text);
}
tr:last-child td {
    border-bottom: 0;
}
tbody tr:nth-child(even) td {
    background: rgba(255, 255, 255, 0.02);
}
.callout {
    margin: 18px 0;
    padding: 14px 18px 14px 18px;
    border-radius: 10px;
    border: 1px solid var(--border);
    border-left-width: 4px;
    background: var(--panel);
}
.callout p {
    margin: 6px 0;
}
.callout-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    margin-bottom: 2px;
}
.callout-warn {
    border-left-color: var(--warn);
}
.callout-warn .callout-label {
    color: var(--warn);
}
.callout-point {
    border-left-color: var(--ok);
}
.callout-point .callout-label {
    color: var(--ok);
}
.callout-note {
    border-left-color: var(--accent);
}
.callout-note .callout-label {
    color: var(--accent);
}
.callout-def {
    border-left-color: #c792ea;
    font-size: 16px;
}
.callout-def .callout-label {
    color: #c792ea;
}
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    margin: 20px 0 26px;
    padding: 22px 16px;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: #0a1626;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
    flex-shrink: 0;
}
.mermaid-diagram p {
    color: inherit;
    margin: 0;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
}
ol,
ul {
    padding-left: 1.4em;
}
.page-footer {
    margin-top: 64px;
    padding-top: 20px;
    border-top: 1px solid var(--border);
    color: var(--faint);
    font-size: 13px;
    line-height: 1.8;
}
@media (max-width: 900px) {
    .toggle {
        display: block;
    }
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.2s;
    }
    .sidebar.open {
        transform: none;
        box-shadow: 0 0 40px rgba(0, 0, 0, 0.6);
    }
    .main {
        margin-left: 0;
        padding: 64px 16px 60px;
    }
    .hero {
        padding: 22px 18px;
    }
    .hero-title {
        font-size: 22px;
    }
    .meta {
        grid-template-columns: minmax(0, 1fr);
    }
    .meta-item {
        padding: 8px 0;
        border-right: 0;
        border-bottom: 1px solid var(--border);
    }
    .meta-item:last-child {
        border-bottom: 0;
    }
    h2 {
        font-size: 20px;
    }
}

